"На этот раз смеются все. Я замечаю, как сильно нуждался в самом обычном разговоре, который не требует выбрать сторону. Ужин заканчивается неторопливо. Вера помогает собрать чашки. Аркадий вспоминает о книге, которую хотел мне показать, и зовёт на минуту в кабинет."
